const body=lines.slice(open+1,close);
const text=body.join("\n")+"\n";
fs.writeFileSync("packages/runner/test/run/fixtures/system-prompt-5.1.txt", text);
const ts = [
"/**",
" * The static system prompt of every run: docs/m2-plan.md section 5.1, verbatim (one string per line, joined with",
" * newlines, ending with one newline). Byte-identical across runs and projects so the CLI\x27s prompt cache is reused;",
" * everything project-specific goes into the first user turn (section 5.2). Generated from the plan\x27s text (WP3);",
" * test/run/prompts.test.ts compares it with a fixture copy and with the plan itself.",
" */",
"const SYSTEM_PROMPT_LINES: readonly string[] = [",
...body.map(l=>"  "+JSON.stringify(l)+","),
"];",
